import re

def solve(env, goal):
    obs = env.observation
    # parse goal: object type to cool, target receptacle type
    m = re.search(r"cool (?:some |a |an )?([a-z]+) and put it (?:in |on )?([a-z]+)", goal, re.I)
    if not m:
        m = re.search(r"([a-z]+) and put it (?:in |on )?([a-z]+)", goal, re.I)
    obj_type = m.group(1) if m else "bowl"
    rec_type = m.group(2) if m else "shelf"

    # collect receptacles from room description
    receptacles = []
    if obs:
        for name in re.findall(r"(?:a|an) ([a-z]+ \d+)", obs):
            if not re.search(r"\d+$", name.split()[-1]):
                continue
            receptacles.append(name)
    # unique preserving order
    seen = set()
    uniq = []
    for r in receptacles:
        if r not in seen:
            seen.add(r)
            uniq.append(r)
    receptacles = uniq

    def admissible_contains(kw):
        return [a for a in env.admissible() if kw in a]

    def open_rec(rec):
        # ensure receptacle opened if closed
        fb = env.step("open " + rec)
        if "already open" in fb.lower() or "is open" in fb.lower() or "open" in fb.lower():
            pass
        return fb

    def find_obj():
        for rec in receptacles:
            if rec.split()[0] == "fridge" or rec.split()[0] == "microwave":
                continue
            fb = env.step("go to " + rec)
            # open if closed
            if "closed" in fb.lower():
                env.step("open " + rec)
            # look at contents: try to take directly; if not present, look
            inv = env.step("inventory")
            # try take
            for a in env.admissible():
                if a.startswith("take ") and obj_type in a:
                    fb2 = env.step(a)
                    if "pick up" in fb2.lower() or "you take" in fb2.lower():
                        return True
            # also check observation for object presence to open
            if obj_type in env.observation.lower():
                for a in env.admissible():
                    if a.startswith("take ") and obj_type in a:
                        env.step(a)
                        return True
        return False

    # Main: find object
    got = find_obj()
    if not got:
        # maybe object in closed container; scan all receptacles and open
        for rec in receptacles:
            env.step("go to " + rec)
            env.step("open " + rec)
            for a in env.admissible():
                if a.startswith("take ") and obj_type in a:
                    env.step(a)
                    got = True
                    break
            if got:
                break

    # cool with fridge
    fridge = None
    for rec in receptacles:
        if rec.split()[0] == "fridge":
            fridge = rec
            break
    if fridge:
        env.step("go to " + fridge)
        # open fridge if closed
        if "closed" in env.observation.lower():
            env.step("open " + fridge)
        env.step("cool " + obj_type + " 1 with " + fridge) if False else None
        # use generic: find admissible cool command
        for a in env.admissible():
            if a.startswith("cool "):
                env.step(a)
                break

    # put in target receptacle
    target = None
    for rec in receptacles:
        if rec.split()[0] == rec_type:
            target = rec
            break
    if target:
        env.step("go to " + target)
        if "closed" in env.observation.lower():
            env.step("open " + target)
        for a in env.admissible():
            if a.startswith("move "):
                env.step(a)
                break
